    for(const c of data.candidates){const[x,y]=projections.get(c.level)(c.x,c.z);pinBoxes.push({x:x-4*unit,y:y-4*unit,w:8*unit,h:8*unit});}
    const leaders=node('g',{'data-annotation-leaders':''});svg.append(leaders);
    const measure=document.createElement('canvas').getContext('2d');
