        const expanded={x:b.x-3*unit,y:b.y-3*unit,w:b.w+6*unit,h:b.h+6*unit};
        const routeHits=Number(obstacles.some(s=>s.level===level&&overlap(s,expanded)&&segmentHits(s.a,s.b,expanded)));
        return{box:b,collisions,routeHits,score:collisions*1e8+routeHits*1e6+Math.hypot(b.x+b.w/2-x,b.y+b.h/2-y)};
