/* The website fetches its separate media package; route data is not in Git. */
'use strict';
const $ = s => document.querySelector(s);
const NS = 'http://www.w3.org/2000/svg';
const state = {catalog: [], cache: new Map(), base: '', active: null, progress: 0, playing: false, last: 0, limit: 9, map: null, epoch: 0, stage: 2, apply: true, inspected: null, scrubbing:false};
function element(tag, attrs = {}, content) {
  const node = document.createElementNS(NS, tag);
  Object.entries(attrs).forEach(([k, v]) => node.setAttribute(k, v));
  if (content !== undefined) node.textContent = content;
  return node;
}
function sceneLabel(scene) { return `Scene ${[...new Set(state.catalog.map(c=>c.scene))].indexOf(scene)+1}`; }
function familyLabel(family) { return family==='Counting'?'Counts':family; }
function queryView(){return state.stage===(state.active?.judgmentEvidence?.hasRepair?4:2);}
function url(path) { return new URL(path, state.base).href; }
async function fetchJSON(path,{timeout=12000,attempts=2}={}) {
  const boot=window.ReCoNavBootstrap,pathname=new URL(path,document.baseURI).pathname;
  if(boot){
    const mediaIndex=pathname.lastIndexOf('/media/'),key=mediaIndex>=0?decodeURIComponent(pathname.slice(mediaIndex+7)):null;
    if(key&&boot.json[key])return structuredClone(boot.json[key]);
    if(pathname.endsWith('/media-config.json'))return boot.config;
    if(pathname.endsWith('/paper-results.json'))return boot.paper;
    if(key==='catalog.json')return boot.catalog;
  }
  for(let attempt=0;attempt<attempts;attempt++){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);
    try{
      const response=await fetch(path,{cache:'no-store',signal:controller.signal});
      if(!response.ok)throw Error(`Could not load ${pathname} (${response.status})`);
      return await response.json();
    }catch(error){if(attempt===attempts-1)throw controller.signal.aborted?Error(`Request timed out: ${pathname}`):error;}
    finally{clearTimeout(timer);}
  }
}
async function getCase(entry) {
  if (!state.cache.has(entry.id)) state.cache.set(entry.id, fetchJSON(url(entry.json)).catch(error=>{state.cache.delete(entry.id);throw error;}));
  return state.cache.get(entry.id);
}
